#!/usr/bin/env python3
"""Build a static, fail-closed GitHub Pages executive brief from recorded evidence."""
from __future__ import annotations

from datetime import datetime
import html
import hashlib
import json
from pathlib import Path
import shutil

ROOT = Path(__file__).resolve().parents[1]
DOCS = ROOT / "docs"


def esc(x):
    return html.escape(str(x), quote=True)


def layout(title: str, current: str, body: str) -> str:
    nav = [("Overview", "index.html"), ("How to submit", "executive-summary.html"),
           ("CSPES lane", "cspes/index.html"), ("Research", "research.html"), ("Evidence", "evidence.html")]
    links = "".join(f'<a {"class=active" if current == url else ""} href="{url}">{name}</a>' for name, url in nav)
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="description" content="An evidence-first research and submission audit for the DOE GEMS Prize.">
<title>{esc(title)} · GEMS Field Notes</title><link rel="stylesheet" href="assets/styles.css"><script src="assets/status.js" defer></script></head>
<body><header class="topbar"><div class="wrap navrow"><a class="brand" href="index.html"><span class="brandmark">⌁</span><span>GEMS FIELD NOTES<small>FAULT DISCOVERY / RESEARCH</small></span></a>
<nav class="navigation" aria-label="Main navigation">{links}</nav><span class="nav-status"><i class="dot"></i> No file approved</span></div></header>
<main>{body}</main><footer class="footer"><div class="wrap footerrow"><span>GEMS FIELD NOTES · Independent research, not affiliated with DOE or DrivenData.</span><span>Evidence first. No slot spent by this audit.</span></div></footer></body></html>'''


def decision():
    return '''<div class="decision"><div class="decision-inner"><div><div class="decision-label"><i class="dot"></i> Automated verdict · negative</div>
<h2>No competition file is cleared.</h2><p>This lane stopped before modeling. A parallel candidate fails the literal registry rule and footprint check. Historical and concurrent files are research only; format checks alone cannot authorize a submission. The 2026-10-27 CSPES lane generated a format-valid, sparse-registry-unique GeoTIFF, but its holdout verdict is negative and it is not cleared either.</p></div>
<div class="actions"><a class="button" href="cspes/index.html">Open CSPES lane &amp; download <span>↗</span></a><a class="button secondary" href="executive-summary.html">Submission guide <span>↗</span></a></div></div></div>'''


def human_age(feed: dict) -> str:
    if not feed.get("last_success_utc"):
        return "No successful observation"
    try:
        datetime.fromisoformat(feed["last_success_utc"])
    except (ValueError, TypeError):
        return "Invalid observation timestamp"
    prefix = "Latest refresh failed · last success " if feed.get("last_attempt_error") else "Last checked · "
    return prefix + feed["last_success_utc"].replace("+00:00", " UTC")


def historical_h6_section() -> str:
    """Summarize an unreplayed, hash-pinned peer holdout without extrapolating it."""
    h = json.loads((ROOT / 'evidence/h6_1_proximity_pruning_holdout.json').read_text())
    unpruned = h['scores']['unpruned']
    pruned = h['scores']['proximity_prune']
    paired = h['paired_differences']['random_prune']
    baseline = h['paired_differences']['unpruned']
    return f'''<section class="section"><div class="section-head"><div><div class="kicker">Historical holdout / B2 mechanism</div><h2>What can pruning explain?</h2><p>GEMSDOE32 B2 is a subset of GEMSDOE31 H27-4: 2,545 dots were removed 1.41–2.00 pixels from the mirrored fault catalogue. That is a measured change, not proof of the reported score.</p></div><a class="button light" href="data/h6_1_proximity_pruning_holdout.json">Read historical holdout ↓</a></div>
<div class="grid2"><article class="card panel"><h3>HOLDOUT-DTI · H6-1</h3><p>A prior shared-template experiment, not run or independently replayed here, reports evaluator <code>{esc(h['evaluator_version'])}</code> with {unpruned['withheld_positive_pixels']:,} withheld positive pixels. Unpruned DTI was {unpruned['dti']:.5f} (spatial 95% CI {unpruned['ci95'][0]:.5f}–{unpruned['ci95'][1]:.5f}); after ≤2-pixel pruning it was {pruned['dti']:.5f} (CI {pruned['ci95'][0]:.5f}–{pruned['ci95'][1]:.5f}). The paired change was {baseline['delta']:+.5f} (CI {baseline['ci95'][0]:+.5f}–{baseline['ci95'][1]:+.5f}).</p><p>Against equal-count random pruning the paired change was {paired['delta']:+.5f} (CI {paired['ci95'][0]:+.7f}–{paired['ci95'][1]:+.5f}); the source verdict is <strong>{esc(h['verdict'])}</strong>.</p></article><article class="card panel"><h3>The important limitation</h3><p>The saved experiment says its buffered holdout contained no withheld truth within 3 pixels of visible fault context. It therefore cannot identify performance in the near-catalogue regime motivating B2, and its small proxy change cannot prove or disprove an effect on hidden competition labels. The 0.2778 owner report has no receipt here. No new TIFF or score estimate is cleared.</p><p><a href="data/verification_2026-10-27.json">See the independent raster recheck ↗</a></p></article></div></section>'''


def overview(a: dict, feed: dict, concurrent: dict, upstream: dict, recent: dict) -> str:
    rows = []
    heads = {r['site']: r for r in upstream['repositories']}
    changed = sum(r.get('comparison_to_baseline') == 'CHANGED' for r in heads.values())
    failed = sum(r.get('fetch_status') != 'FETCHED' for r in heads.values())
    for row in a["focus_sites"]:
        label = "NO"
        detail = f"{100 * row['max_focus_overlap']:.1f}% vs {row['max_focus_overlap_site']}"
        h = heads[row['site']]
        status = h['comparison_to_baseline'] if h['fetch_status'] == 'FETCHED' else 'UNKNOWN'
        observed = h.get('observed_head') or ''
        sha_link = (f'<a href="https://github.com/{esc(h["repo"])}/commit/{esc(observed)}">{esc(observed[:8])} ↗</a>'
                    if observed else 'No observation')
        freshness = human_age(h)
        rows.append(f'''<tr><td class="site">{esc(row['site'])}</td><td><a class="file-link" href="{esc(row['download_research_only'])}">{esc(row['filename'])} ↗</a><small>Historical reference · research only</small></td>
<td><strong>{esc(row['claimed_by_owner_not_receipt'])}</strong><br><small>Owner report · unverified</small></td><td><span class="flag muted">Not estimable</span></td><td><span class="flag no">{label}</span><br><small>{esc(detail)}</small></td><td><span class="flag {'no' if status != 'UNCHANGED' else 'ok'}">{esc(status)}</span><br>{sha_link}<small data-freshness data-checked="{esc(h.get('last_success_utc') or '')}" data-error="{'yes' if h['fetch_status'] != 'FETCHED' else 'no'}">{esc(freshness)}</small></td><td><span class="flag no">DO NOT SUBMIT</span></td></tr>''')
    leader = feed.get("best_public_dti") or "—"
    step = concurrent['artifacts']['step_zeros']
    peer = {r['site']: r for r in recent['artifacts']}
    return f'''<section class="hero"><div class="wrap"><div class="eyebrow">Independent research brief / DOE GEMS Prize</div><div class="title-line"><div><h1>Find better faults.<br>Trust the evidence.</h1><p class="subhead">A clear view of the submission decision, scientific evidence, and what to do next.</p></div><div class="date-chip">LAST AUDIT / {esc(a['checked_utc'][:10])} UTC</div></div>{decision()}

<div class="stats"><div class="stat"><span class="stat-label">Submission status</span><strong>STOP</strong><small>Literal registry rule blocks release</small></div><div class="stat"><span class="stat-label">Highest historical claim</span><strong>0.2778</strong><small>Owner-reported · not receipt-confirmed</small></div><div class="stat"><span class="stat-label"><a href="https://www.drivendata.org/competitions/306/competition-doe-gems/leaderboard/">Public leaderboard leader ↗</a></span><strong>{esc(leader)}</strong><small id="feed-freshness" data-freshness data-checked="{esc(feed.get('last_success_utc') or '')}" data-error="{'yes' if feed.get('last_attempt_error') else 'no'}">{esc(human_age(feed))} · not our score</small></div><div class="stat"><span class="stat-label">Weekly slots spent here</span><strong>0</strong><small>No model experiment run by this audit</small></div></div></div></section>
<div class="wrap content"><section class="section" id="cspes-lane"><div class="section-head"><div><div class="kicker">New / 2026-10-27 CSPES lane</div><h2>A unique TIF was generated — and honestly scored negative.</h2><p>The cross-scale potential-field edge-stability lane ran three experiments with canaries and the shared hide-and-recover evaluator. The downloadable GeoTIFF passes every format gate and is unique against 117 rebuilt sparse historical masks, but HOLDOUT-DTI 0.0257 (CI 0.0194–0.0319) loses to the 0.0992 incumbent; do not promote it to a slot.</p></div><a class="button light" href="cspes/index.html">Open lane executive summary ↓</a></div><div class="grid2"><article class="card panel"><h3>What passed</h3><ul><li>single-feature canary AUCs 0.47–0.57 — no leakage alarm</li><li>shared fail-closed writer; independent validator PASS; all values finite in [0,1], zero NaN</li><li>U1 no exact duplicate; U2 max |Spearman| 0.108; U3 max 3-px overlap 62.3% ≤ 70%</li></ul></article><article class="card panel"><h3>What failed / stays blocked</h3><ul><li>paired Δ vs incumbent −0.0736 (95% CI −0.0883 to −0.0587); not predictive over random at any budget</li><li>literal any-raster rule still impossible: the dense 17GEMSDOE witness overlaps every nonempty raster 100%</li><li>verdict <strong>negative</strong>; 0 weekly slots spent; selector owns any future promotion</li></ul></article></div></section>
<div class="wrap content"><section class="section" id="focus"><div class="section-head"><div><div class="kicker">01 / The nine-site review</div><h2>Historical references, not submissions</h2><p>Highest historical claims in the pinned snapshot, compared against the other eight pinned files. Current best files and scores are unverified; no receipt ties a claim to an uploaded hash.</p></div><a class="button light" href="data/focus_audit.json" download>Download full audit ↓</a></div>
<p class="scroll-hint">Swipe across the table to see all columns →</p><div class="card table-card" tabindex="0" role="region" aria-label="Historical focus-site comparisons; scroll horizontally for all columns"><table class="table"><thead><tr><th>Site</th><th>File to download</th><th>Owner claim</th><th>Estimate</th><th>Unique vs 8?</th><th>Source HEAD</th><th>Action</th></tr></thead><tbody>{''.join(rows)}</tbody></table></div><p class="note">Uniqueness uses directional fraction of positive pixels within 3 pixels and absolute full-footprint binary Spearman. Each is also blocked by the registered dense witness; no historical file is recommended for upload. A holdout proxy is not a leaderboard estimate.</p><p class="note"><strong>Source freshness:</strong> {changed} of 9 repository HEADs changed since the 2026-10-26 audit; {failed} latest checks failed. A changed HEAD is a drift warning, not proof that a particular file or score changed. <a href="data/latest-upstream-check.json">Per-repository identity checks ↗</a>. Last checked {esc(upstream['checked_at'])}.</p></section>
{historical_h6_section()}

<section class="section"><div class="section-head"><div><div class="kicker">Concurrent work / Independent review</div><h2>A parallel candidate is not cleared.</h2></div><a class="button light" href="data/concurrent_audit.json" download>Download artifact audit ↓</a></div><div class="grid2"><article class="card panel"><h3>35,000 dots, literal registry failure</h3><p>A separate agent merged a step-over raster while this audit was underway. <strong>{100 * step['forward_overlap_registered_witness']:.2f}%</strong> of all its {step['positive_cells']:,} dots fall within 3 px of the registered witness; <strong>{100 * step['inside_footprint_overlap_registered_witness']:.0f}%</strong> of its in-footprint dots overlap. Both exceed 70%. The earlier 58-reference pass did not include this witness.</p><p>Its saved bytes also contain <strong>{step['outside_mirrored_footprint']:,}</strong> positive cells outside the mirrored sample footprint and <strong>{step['on_mirrored_catalogue_inside_footprint']:,}</strong> on mirrored mapped faults. These are measured file properties, not evidence of portal acceptance.</p><div class="callout">DO NOT SUBMIT. The file is preserved for research; its preceding uniqueness and format claims are superseded by this pinned audit.</div></article><article class="card panel"><h3>Other files are stand-ins</h3><p>Another parallel site advertises a synthetic <strong>1,200 × 1,600</strong> raster. A separate archived synthetic TIFF is <strong>1,024 × 1,024</strong>. Neither matches the mirrored <strong>3,730 × 3,292</strong> competition grid; neither is a competition submission.</p><p>The step-over “nan” twin has the same decoded positive pixels as the zero version and a NaN nodata tag, but its stored array contains no NaNs. No feature canaries, withheld-segment score, score receipt, or current account quota was verified here.</p><a href="evidence.html">See artifact details →</a></article></div></section>
<section class="section"><div class="section-head"><div><div class="kicker">Recent peer artifacts / read-only follow-up</div><h2>Two newer files hit the same stop.</h2><p>We re-read the exact featured bytes, not just the older site table. These checks do not replay their holdouts.</p></div><a class="button light" href="data/recent_peer_audit.json">Read peer audit ↗</a></div><div class="grid2"><article class="card panel"><h3>GEMSDOE28 · S22-CTXHGB</h3><p><a href="{esc(peer['GEMSDOE28']['source'])}">{esc(peer['GEMSDOE28']['source_filename'])} ↗</a> is a research reference only. All <strong>{peer['GEMSDOE28']['positive_inside']:,} positive cells</strong> overlap the witness at distance zero, violating the literal rule. Its source reports a local promote but also flags incomplete global registry and no slot selection; its projection is not a score.</p><div class="callout">DO NOT SUBMIT · score not estimable</div></article><article class="card panel"><h3>GEMSDOE36 · KPL-36</h3><p><a href="{esc(peer['GEMSDOE36']['source'])}">{esc(peer['GEMSDOE36']['source_filename'])} ↗</a> also has <strong>{peer['GEMSDOE36']['positive_inside']:,} positives</strong> and 100% witness overlap. The newer source README supersedes an earlier upload recommendation with DO NOT SUBMIT. Its reported holdout and user score have not been independently verified.</p><div class="callout">DO NOT SUBMIT · no receipt</div></article></div></section>
<section class="section"><div class="grid2"><article class="card panel"><h3>Historical LST1 files also fail.</h3><p>Both archived variants have <strong>100% overlap</strong> with the registered witness. Their earlier uniqueness exemptions and upload-readiness claims are superseded. The former holdout used fixed historical rasters and full-catalogue-derived inputs; fold-local compliance is not established.</p><p><a href="lst1/index.html">Open the research-only LST1 archive →</a></p></article><article class="card panel"><h3>Scores are not interchangeable.</h3><p>A measured public leaderboard leader belongs to another participant, not a project file. Owner-reported historical claims have no receipt, a projection is not a score, and current candidate HOLDOUT-DTI is unknown because no model was run.</p></article></div></section>
<section class="section"><div class="section-head"><div><div class="kicker">02 / The stop, explained</div><h2>A rule conflict, proven from the rasters</h2></div></div><div class="grid2"><article class="card panel"><h3>One reference covers the entire footprint.</h3><p>Under the shared template, a “dot” is any finite value greater than zero. A registered 17GEMSDOE probability raster is positive at all <strong>5,167,373 of 5,167,373</strong> allowed cells. Every nonempty in-footprint prediction therefore overlaps it at distance zero: <strong>100%</strong>, exceeding the requested 70% stop.</p><div class="callout">This is a proof about the literal definition, not a claim that every probability pixel is geologically a dot. No exemption was silently introduced.</div><div class="anchor-list"><a href="evidence.html">See the byte-level proof →</a></div></article>
<article class="card panel"><h3>What is still unknown?</h3><ul><li>This lane built no surface, so its feature AUC canaries and blocked holdout were not run.</li><li>The data were restored from a hash-pinned public mirror, not independently authenticated by DrivenData.</li><li>The earlier range error’s cause is unknown. The official outside-bounds wording and the shared all-finite writer differ; portal acceptance is unverified.</li><li>The current weekly quota and private fault labels require competition-account access.</li></ul></article></div></section>
<section class="section"><div class="section-head"><div><div class="kicker">03 / Understand the incumbent</div><h2>Why did the B2 family do well?</h2></div></div><div class="grid2"><article class="card panel"><h3>What the files show</h3><p>GEMSDOE32’s B2 raster is an exact in-footprint subset of a GEMSDOE28 H27-4 base: <strong>37,654</strong> dots retained from <strong>40,199</strong>, with <strong>2,545</strong> removed near mapped faults. This is a decoded-pixel measurement, not a verified explanation of a score.</p><p>Under the official 300 m triangular kernel, nearby predictions can cover fault pixels, while redundant or distant predictions can add false-positive cost. The low false-positive weight may favor broad recovery. Hidden labels and authenticated receipts are unavailable, so the causal explanation remains a hypothesis.</p></article><article class="card panel"><h3>Can a new method beat it?</h3><p><strong>Unknown.</strong> No matched holdout result or calibrated leaderboard forecast was produced here. Renaming, changing nodata encoding, or perturbing the old raster would not prove uniqueness or scientific improvement.</p><p>The next proposed lane tests cross-scale agreement of magnetic and gravity edges, with lithologic contacts and survey stripes as explicit non-fault mimics. It remains untested behind the stop.</p><a href="research.html">Read hypotheses and sources →</a></article></div></section>
<section class="section"><div class="section-head"><div><div class="kicker">04 / Next steps</div><h2>Keep the path to a real submission clear.</h2></div></div><div class="steps"><article class="card step"><span class="step-number">01</span><div><h3>Resolve the literal registry conflict</h3><p>A protocol owner must explicitly define how continuous or space-filling references are treated. Until then the current instruction remains binding; a different name or raster cannot bypass the witness.</p></div></article><article class="card step"><span class="step-number">02</span><div><h3>Run the frozen lane on the shared evaluator</h3><p>First check every feature for leakage, then use buffered whole-segment holdouts, visible-only catalogue features and paired spatial-block confidence intervals.</p></div></article><article class="card step"><span class="step-number">03</span><div><h3>Validate exact bytes, then use a separate selector</h3><p>Only a unique holdout winner gets a locally validated GeoTIFF and a distinct name/note. A separate selector must account for the live weekly limit before upload.</p></div></article></div></section>
<section class="section"><div class="section-head"><div><div class="kicker">05 / Primary sources</div><h2>Follow the evidence.</h2></div></div><div class="sources"><article class="card source"><span>Competition</span><h3><a href="https://www.drivendata.org/competitions/306/competition-doe-gems/page/967/">Problem &amp; metric ↗</a></h3><p>Official target, spatial data, distance-weighted Tversky formula and GeoTIFF format.</p></article><article class="card source"><span>Federal data</span><h3><a href="https://www.usgs.gov/data/geodawn-airborne-magnetic-and-radiometric-surveys-northwestern-great-basin-nevada-and">USGS GeoDAWN ↗</a></h3><p>Airborne magnetic/radiometric survey details, limitations and public data release.</p></article><article class="card source"><span>Rules</span><h3><a href="https://docs.nlr.gov/docs/fy26osti/96647.pdf">Official prize rules ↗</a></h3><p>Eligibility, weekly limit, AI disclosure and delivery requirements.</p></article></div></section></div>'''


def guide() -> str:
    return f'''<section class="hero"><div class="wrap"><div class="eyebrow">Executive summary / Submission guide</div><div class="title-line"><div><h1>How to submit,<br>when it is ready.</h1><p class="subhead">The checklist is automatic; a portal upload is a separate, explicitly authorized action.</p></div></div>{decision()}</div></section>
<div class="wrap content"><section class="section"><div class="section-head"><div><div class="kicker">Current state</div><h2>There is no cleared file to upload today.</h2><p>Do not submit old references, a renamed copy, or a research-only artifact.</p></div></div><div class="card panel"><div class="readiness"><i class="dot"></i> NOT OK TO SUBMIT · no TIFF is cleared</div><p style="margin-top:12px">Submission name: none. Submission note: none. The decision is produced from raster bytes and the literal registry rule. It does not require a human geologic inspection. An upload action would require an authenticated competition account, which this environment does not have.</p></div></section>
<section class="section"><div class="section-head"><div><div class="kicker">Only after all gates pass</div><h2>Steps at the competition portal</h2></div></div><div class="steps"><article class="card step"><span class="step-number">01</span><div><h3>Confirm an approved, unique file</h3><p>Open this page and verify that the automatic candidate, feature canaries, same-evaluator holdout, full literal registry checks, saved-file validator and separate weekly selector all pass. The parallel candidate fails the registry and footprint checks; no release has cleared the full sequence.</p></div></article><article class="card step"><span class="step-number">02</span><div><h3>Download the exact approved GeoTIFF</h3><p>Use the download shown beside its SHA-256 and compare the bytes with its receipt. The file must be one float32 band, match the sample CRS, shape and transform, and have no nonfinite or out-of-range values in the footprint. The official text requires null/NaN outside bounds, whereas the shared writer emits unmasked zeros outside the mirrored footprint. Confirm the meaning of bounds with organizers and reconcile the shared writer before upload.</p></div></article><article class="card step"><span class="step-number">03</span><div><h3>Check available weekly slots</h3><p>Sign in to <a href="https://www.drivendata.org/competitions/306/competition-doe-gems/">DrivenData GEMS</a>. The official rules state up to three submissions per week; check the live portal and team quota before using one. We cannot see your account quota.</p></div></article><article class="card step"><span class="step-number">04</span><div><h3>Upload once, with the approved note</h3><p>Follow the current portal prompts to choose the exact approved GeoTIFF and paste the generated name/note if supported (note ≤ 140 characters in this project). The official problem specifies a GeoTIFF; current ZIP acceptance has not been independently verified. Preserve the organizer receipt and uploaded hash together. Do not report a local holdout as a portal result.</p></div></article><article class="card step"><span class="step-number">05</span><div><h3>Select one final submission before the deadline</h3><p>The same selected submission is scored for both prize rounds. The homepage listed Dec. 3, 2026 at 23:59 UTC when checked; the rules appendix mentions 5 p.m. ET. Confirm the applicable deadline with organizers and do not wait until either cutoff. Review eligibility, reproducible code, external-data licensing and the required disclosure of generative AI use in the <a href="https://docs.nlr.gov/docs/fy26osti/96647.pdf">official rules</a>.</p></div></article></div></section>
<section class="section"><div class="grid2"><article class="card panel"><h3>About the range error</h3><p>“Predicted values must be in range [0, 1]” can reflect invalid values or an encoding issue, but the exact cause of the reported rejection has not been established. The writer rejects NaN, infinities, sentinels and values outside [0,1] rather than silently clipping predictions. The official text says outside bounds must be null/NaN, but the mirrored sample has NaNs outside its footprint and the shared writer emits unmasked zeros. The meaning of bounds and acceptance are unresolved; investigate with organizers and reconcile the shared writer before any future upload.</p></article><article class="card panel"><h3>Automated checks are necessary, not sufficient</h3><p>A file passing the local validator is only structurally compatible with the mirrored sample. It still needs uniqueness, leakage, scientifically valid holdout, and selector approval. The hidden test labels remain inaccessible.</p><a href="evidence.html">Review the negative run card →</a></article></div></section></div>'''


def research() -> str:
    return f'''<section class="hero"><div class="wrap"><div class="eyebrow">Research / Preregistered hypotheses</div><div class="title-line"><div><h1>Evidence before<br>experimentation.</h1><p class="subhead">Four reasoned ideas. Only one provisional lane; none was run after the mandatory stop.</p></div></div>{decision()}</div></section><div class="wrap content"><section class="section"><div class="section-head"><div><div class="kicker">Hypothesis queue</div><h2>Promising signals, explicit confounders.</h2><p>Priority is qualitative, not an estimate of leaderboard gain. Novelty has not been established across all other projects.</p></div><a class="button light" href="https://github.com/wingbangboozle1-lang/WBGGEMSDOE3/blob/main/knowledge/preregistration-2026-10-26.md">Read preregistration ↗</a></div><div class="grid-list"><article class="card research-card"><span class="rank">01 · Proposed lane / medium cost</span><h3>Cross-scale potential-field edge stability</h3><p>Prespecified gradient alignment and persistence in gravity and reduced-to-pole magnetics, conditioned on detrended elevation. Buried offsets could lack a visible scarp. <strong>Mimic:</strong> lithologic contacts or survey stripes. Uses the cached 19-band mirror.</p></article><article class="card research-card"><span class="rank">02 · Data blocked / high cost</span><h3>Consistent displaced channel corridors</h3><p>Use 3DEP DEM and drainage lines to look for several coherent offsets across one lineament. <strong>Mimic:</strong> erosion, fans and artificial diversions. The free official source is known; competition-tile availability here is not verified.</p></article><article class="card research-card"><span class="rank">03 · Alternative / medium cost</span><h3>Gravity–magnetic edge disagreement</h3><p>Examine scale-stable density boundaries without a matching magnetic boundary, conditioned on geodetic shear. <strong>Mimic:</strong> nonmagnetic lithologic contacts and interpolation. Related potential-field work already exists.</p></article><article class="card research-card"><span class="rank">04 · Data blocked / high cost</span><h3>Thermal contrast, normalized by sampling</h3><p>Compare INGENIOUS probe and spring temperatures to local sampling effort and structure. <strong>Mimic:</strong> groundwater flow or biased sampling. The public GDR listing has CC BY 4.0 data; bytes and local coverage remain unchecked.</p></article></div></section><section class="section"><div class="grid2"><article class="card panel"><h3>Faults are the target, not vents.</h3><p>The competition asks for surface fault probabilities. Faults can create pathways for geothermal fluids, but neither a magnetic edge nor a mapped fault establishes a vent or commercially viable resource.</p><p>The official GeoDAWN survey explains variable aircraft terrain clearance and different acquisition spacings. Cross-scale signals may reflect acquisition and processing, not tectonics; the model must test those confounders.</p></article><article class="card panel"><h3>Evidence hierarchy</h3><ul><li><strong>Organizer receipt:</strong> a submission score linked to uploaded bytes. None available here.</li><li><strong>HOLDOUT-DTI:</strong> a local recovery proxy, with evaluator version, positives and spatial CI. Not a leaderboard score.</li><li><strong>Owner report:</strong> a historical claim without receipt verification.</li><li><strong>Projection:</strong> a model output, never an observed score.</li></ul></article></div></section><section class="section"><div class="section-head"><div><div class="kicker">Trusted references</div><h2>Sources for further review</h2><p>See the <a href="https://github.com/wingbangboozle1-lang/WBGGEMSDOE3/blob/main/knowledge/scientific-review-2026-10-26.md">scientific review</a> for physical confounders, evaluation limits and metric reasoning.</p></div></div><div class="sources"><article class="card source"><span>USGS / JOURNAL</span><h3><a href="https://www.usgs.gov/publications/discovery-a-blind-geothermal-system-southern-gabbs-valley-western-nevada-through">Southern Gabbs Valley ↗</a></h3><p>A documented blind-system case study; not validation of our predictions.</p></article><article class="card source"><span>USGS</span><h3><a href="https://www.usgs.gov/data/maps-elevation-trend-and-detrended-elevation-great-basin-usa">Detrended elevation ↗</a></h3><p>Great Basin structural context; 30 m source, CC0 1.0.</p></article><article class="card source"><span>USGS / JOURNAL</span><h3><a href="https://pubs.usgs.gov/publication/70196066">Stress at discontinuities ↗</a></h3><p>Structural permeability mechanisms and limitations.</p></article><article class="card source"><span>USGS</span><h3><a href="https://www.usgs.gov/programs/earthquake-hazards/science/tectonic-geomorphology-and-near-field-geodesy">Tectonic geomorphology ↗</a></h3><p>Fault scarps and offset streams as clues, not proof.</p></article><article class="card source"><span>USGS</span><h3><a href="https://www.usgs.gov/3d-elevation-program">3DEP elevation ↗</a></h3><p>Free, unrestricted topographic products; AOI tiles still need verifying.</p></article><article class="card source"><span>DOE / GDR</span><h3><a href="https://gdr.openei.org/submissions/1391">INGENIOUS compilation ↗</a></h3><p>Public geothermal features, faults and measurements; CC BY 4.0.</p></article></div></section></div>'''


def evidence(a: dict) -> str:
    return f'''<section class="hero"><div class="wrap"><div class="eyebrow">Evidence / Reproducibility</div><div class="title-line"><div><h1>Show the work.<br>Keep the limits.</h1><p class="subhead">Every current decision is tied to a reproducible observation, not a projected score.</p></div></div>{decision()}</div></section><div class="wrap content"><section class="section"><div class="section-head"><div><div class="kicker">Literal duplicate witness</div><h2>The short proof</h2></div><a href="data/focus_audit.json" class="button light" download>Download audit JSON ↓</a></div><div class="grid2"><article class="card panel"><h3>Measured from the pinned GeoTIFFs</h3><p>The mirrored sample has <strong>5,167,373</strong> finite footprint cells. The registered 17GEMSDOE soft raster has finite, positive values on all of them; its grid matches the sample. Therefore, any nonempty in-footprint prediction intersects that support at each of its own pixels. Its forward 3-pixel overlap is necessarily 100%.</p><p>Witness SHA-256 <code>ab0a0a62eecf066a82713b09dd49f0f638a91fa3dd81f54cc34ae89afa3872be</code>. <a href="{esc(a['witness']['source'])}">Review pinned source ↗</a></p><div class="callout">The independent spacing-5 lattice covers 99.871% of footprint cells within 3 pixels, but it is <em>not</em> a universal blocker by itself. The dense soft raster is the conclusive witness.</div></article><article class="card panel"><h3>Conflicting recommendation elsewhere</h3><p>An older GEMSDOE27 section recommended H31 after a narrower 27-raster check; a newer notice requires a separate selector and does not authorize an upload. We reread the specified all-finite bytes: the local shared format report passes, but <strong>100%</strong> of its {a['gems27_h31_conflicting_site_advice']['positive_pixels']:,} positive pixels overlap the registered dense witness within 3 pixels. Under this request’s literal any-registry rule: <strong>DO NOT SUBMIT.</strong></p><p>That audit does not replay its surface or holdout. <a href="{esc(a['gems27_h31_conflicting_site_advice']['source'])}">Inspect the pinned historical artifact ↗</a></p></article></div></section>
<section class="section"><div class="section-head"><div><div class="kicker">Reproduce locally</div><h2>One shared template; no private evaluator.</h2></div></div><div class="card panel"><p>The data restoration command retrieves the pinned shared template and its SHA-verified public bridge, then builds its 19 cached bands. The audit command re-downloads pinned reference files, compares decoded masks and checks the universal witness. Large data and caches stay out of Git.</p><div class="codeblock"><code>bash scripts/restore_shared_data.sh<br>.venv/bin/python scripts/audit_focus.py<br>.venv/bin/python scripts/audit_archive.py<br>.venv/bin/python scripts/audit_peer_releases.py<br>.venv/bin/python -m pytest -q</code></div><p class="footnote">A successful audit can return a negative verdict. It never selects a submission or spends a portal slot. The mirrored input sample is not an organizer receipt; its positive values conflict with the public description of an all-absence example, so only its grid and footprint are used.</p></div></section>
<section class="section"><div class="grid2"><article class="card panel"><h3>Run card</h3><p>This lane produced no candidate surface, feature canary, holdout score, raster hash, or new-file validator output. A separate parallel candidate was reviewed and failed. The negative card deliberately records them as not run rather than filling in estimates.</p><p><a href="data/run_card.json" download>Download JSON run card ↓</a></p></article><article class="card panel"><h3>Audit boundaries</h3><p>One witness is sufficient to prove failure; it does not establish a complete current registry inventory. The nine-site ranking is based on user/owner claims with no authenticated submission-page receipts, and earlier experiments are not replayed.</p><p>The shared uniqueness tool checks positive rank correlation only, while this request requires absolute correlation. Our independent comparison uses the requested two-sided threshold; the shared tool needs an upstream fix before any future clearance.</p></article></div></section></div>'''


def main():
    a = json.loads((ROOT / "evidence/focus_audit.json").read_text())
    card = json.loads((ROOT / "evidence/run_card.json").read_text())
    feed = json.loads((ROOT / "registry/leaderboard.json").read_text())
    concurrent = json.loads((ROOT / "evidence/concurrent_audit.json").read_text())
    upstream = json.loads((ROOT / "evidence/latest-upstream-check.json").read_text())
    recent = json.loads((ROOT / "evidence/recent_peer_audit.json").read_text())
    expected_peers = {r['site']: r['sha256'] for r in json.loads((ROOT / 'registry/recent_featured.json').read_text())['artifacts']}
    verification = json.loads((ROOT / 'evidence/verification_2026-10-27.json').read_text())
    h6_sha = hashlib.sha256((ROOT / 'evidence/h6_1_proximity_pruning_holdout.json').read_bytes()).hexdigest()
    if (not verification.get('all_passed') or verification.get('candidate_created') is not False or
            h6_sha != 'd477facac6ba82fe922e5cc075e17c644d9c946c5d192d16f9489238056c11dc' or
            verification.get('holdout_h6_1', {}).get('source_sha256') != h6_sha):
        raise ValueError('Historical H6-1 or independent raster verification is missing or changed')
    if (recent.get('approved_for_submission') is not False or len(recent.get('artifacts', [])) != 2 or
            {r['site']: r['sha256'] for r in recent['artifacts']} != expected_peers or
            any(r.get('forward_overlap_witness_within_3px_all_positive') != 1.0 or r.get('approved_for_submission') is not False for r in recent['artifacts'])):
        raise ValueError('Recent peer evidence does not support a negative release decision')
    if (upstream.get('approved_for_submission') is not False or
            {r.get('site') for r in upstream.get('repositories', [])} != {r['site'] for r in a['focus_sites']} or
            len(upstream['repositories']) != len(a['focus_sites'])):
        raise ValueError('Upstream identity feed is incomplete or implies approval')
    source_hash = hashlib.sha256((ROOT / "evidence/focus_audit.json").read_bytes()).hexdigest()
    parallel_hash = hashlib.sha256((ROOT / "evidence/concurrent_audit.json").read_bytes()).hexdigest()
    if (a.get("status") != "STOP_DUPLICATE_UNIVERSAL_WITNESS" or not a["witness"].get("universal_blocker")
            or card.get("verdict") != "negative" or card.get("source_audit_sha256") != source_hash
            or card.get("parallel_artifact_review", {}).get("evidence_sha256") != parallel_hash
            or concurrent['artifacts']['step_zeros']['eligible_to_submit']):
        raise ValueError("Evidence does not support this static negative site; fail closed and review before publishing")
    DOCS.mkdir(exist_ok=True)
    (DOCS / "data").mkdir(exist_ok=True)
    for file in ("focus_audit.json", "concurrent_audit.json", "run_card.json", "data_restore.json", "archive_audit.json", "latest-upstream-check.json", "recent_peer_audit.json",
                 "verification_2026-10-27.json", "h6_1_proximity_pruning_holdout.json",
                 "leaderboard_observation_2026-10-27.json"):
        shutil.copyfile(ROOT / "evidence" / file, DOCS / "data" / file)
    shutil.copyfile(ROOT / "registry/leaderboard.json", DOCS / "data/leaderboard.json")
    pages = {"index.html": ("Overview", overview(a, feed, concurrent, upstream, recent)), "executive-summary.html": ("How to submit", guide()),
             "research.html": ("Research", research()), "evidence.html": ("Evidence", evidence(a))}
    for filename, (title, body) in pages.items():
        (DOCS / filename).write_text(layout(title, filename, body), encoding="utf-8")
    from build_site_lst1 import build as build_archive
    build_archive()
    print(f"Built {len(pages)} pages and the research-only archive from negative evidence.")


def build():
    """Compatibility alias for the preserved site reproducibility tests."""
    main()


if __name__ == "__main__":
    main()
